function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: {type: 'list_sessions'; limit?: number; before?: {sessionId: string; updatedAt: string | number}} = {
    type: 'list_sessions',
  };

  if ('limit' in message && isInvalidLimit(message.limit)) {
    return {valid: false, error: 'limit must be a non-negative integer'};
  }

  if ('limit' in message) {
    result.limit = message.limit as number;
  }

  if (!('before' in message)) {
    return {valid: true, data: result as IncomingMessage};
  }

  const before = message.before;
  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'before must be an object'};
  }

  const b = before as Record<string, unknown>;

  if (typeof b.sessionId !== 'string' || b.sessionId.length < 1 || b.sessionId.length > 128) {
    return {valid: false, error: 'before.sessionId must be a string of length 1-128'};
  }

  const isInvalidString = typeof b.updatedAt === 'string' && Number.isNaN(Date.parse(b.updatedAt));
  const isInvalidNumber = typeof b.updatedAt === 'number' && !Number.isFinite(b.updatedAt);
  const isInvalidType = typeof b.updatedAt !== 'string' && typeof b.updatedAt !== 'number';

  if (isInvalidString || isInvalidNumber || isInvalidType) {
    return {valid: false, error: 'before.updatedAt must be a valid ISO date string or a finite number'};
  }

  result.before = {
    sessionId: b.sessionId,
    updatedAt: b.updatedAt as string | number,
  };

  return {
    valid: true,
    data: result as IncomingMessage,
  };
}

